/**
 * The settings registry (#115, spec runs/2026-10-24/run-profiles/spec.md 1): every MC_* and MCAI_* setting the server
 * reads, with its type, its default (the value the code uses when the setting is unset, as the environment would give
 * it), a description, its group (the panel's), whether it may change during a run, and what it requires. Every read goes
 * through rawSetting(), which gives what process.env gives (or a live change, later): each read site keeps its own
 * parsing, so the registry changes no behaviour. scripts/checks/settings_reads.mts fails on a read outside it, an entry
 * never read, or a default that differs from the code's; scripts/settings_doc.mts writes the table.
 */

export type SettingType = 'flag' | 'number' | 'string';
export type SettingGroup = 'speed' | 'models' | 'building' | 'economy' | 'social' | 'character' | 'ladder' | 'needs' | 'choices' | 'server' | 'debug';

export interface Setting {
  name: string;
  type: SettingType;
  /** The value the code uses when unset, in the environment's form ('' for nothing). */
  default: string;
  group: SettingGroup;
  /** Whether it may change during a run (step 4); every setting is start-only until its uses are checked. */
  live: boolean;
  /** The values it takes, when it takes only these ('' aside). */
  values?: string[];
  /** Settings it does nothing without. */
  requires?: string[];
  /** Run kinds it must not be raised in (warnings in a profile's validation). */
  notIn?: Array<'acceptance'>;
  /** The files that read it (for the doc table). */
  read: string;
  describe: string;
}

